mapper.select:
SELECT *
FROM lunaerp_business_shipment_item
WHERE shipment_id = #{shipmentId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_business_shipment_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE shipment_id = #{shipmentId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_business_shipment_item
WHERE shipment_id = #{shipmentId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
